# build_fig_appendix_aggregate_self_regarding.R
#
# DEMOTED from Figure 3.3 to an appendix item, 7 Sep 2026 — PJ: "I think it
# makes sense to have that as the figure now, the split" (i.e. the backbench/
# frontbench split, see build_fig_3_3_hansard_self_regarding.R, now takes the
# Figure 3.3 slot). This script preserves the original single-line aggregate
# 1979-2025 chart as a supporting appendix figure, not deleted — full-span
# coverage (including 2020-25, which the split doesn't have yet) still has
# value as the headline-number reference.
#
# OUTPUT: figures/ch3_aggregate_self_regarding_APPENDIX.png

suppressMessages({library(dplyr); library(readr); library(ggplot2)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

d <- read_csv(file.path(PROJECT, "data/processed/speech_self_regarding_1979_2025.csv"),
              show_col_types = FALSE) |>
  arrange(year) |>
  mutate(lo = mean_self_ratio - 1.96 * se_self_ratio,
         hi = mean_self_ratio + 1.96 * se_self_ratio)

overall_mean <- mean(d$mean_self_ratio)
CANVAS_W <- house_width_in()
ci_x <- 1982
ci_y <- d$hi[d$year == ci_x] + 0.006

p <- ggplot(d, aes(year, mean_self_ratio)) +
  geom_ribbon(aes(ymin = lo, ymax = hi), fill = "grey85", colour = NA) +
  geom_hline(yintercept = overall_mean, linetype = "dashed",
             colour = "grey55", linewidth = 0.4) +
  geom_line(colour = "#000000", linewidth = 0.8) +
  geom_point(colour = "#000000", size = 0.9) +
  annotate("text", x = ci_x, y = ci_y, label = "95% CI",
           colour = "grey45", fontface = "italic",
           size = mm_for(PRINTED$caption, CANVAS_W)) +
  scale_x_continuous(breaks = seq(1980, 2020, 10), limits = c(1979, 2025)) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
  labs(
    title = paste0(
      "Self-regarding speech in the House of Commons,\n",
      "1979-2025 (aggregate, all speakers)"
    ),
    x = NULL, y = "Self-regarding ratio (mean)"
  ) +
  house_print(CANVAS_W)

OUT <- file.path(PROJECT, "figures/ch3_aggregate_self_regarding_APPENDIX.png")
ggsave(OUT, p, width = CANVAS_W, height = CANVAS_W * 0.55, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")

# ============================================================
# NOTES — generated so numbers cannot drift from the figure, same rigour
# as Figure 3.3's FIG33_FOOTNOTE_NOTES.md
# ============================================================
period <- function(y0, y1) mean(d$mean_self_ratio[d$year >= y0 & d$year <= y1])
p1 <- period(1979, 1988); p2 <- period(1989, 1997); p3 <- period(1998, 2009)
p4 <- period(2010, 2019); p5 <- period(2020, 2025)
lowest_year <- d$year[which.min(d$mean_self_ratio)]
lowest_val  <- min(d$mean_self_ratio)

notes <- c(
"# Appendix aggregate self-regarding figure - notes",
"",
"⚠ GENERATED by build_fig_appendix_aggregate_self_regarding.R. Every number below is computed",
"from data/processed/speech_self_regarding_1979_2025.csv at build time - nothing hand-typed.",
"",
sprintf("Built %s. N = %d years, %d-%d, zero gaps. Chamber+Westminster Hall throughout", Sys.Date(), nrow(d), min(d$year), max(d$year)),
"(Blumenau & Damiani 1979-2019, live Hansard API 2020-25) — same underlying series as Figure 3.3,",
"aggregated across ALL speakers rather than split by backbench/frontbench.",
"",
"## Period means",
sprintf("- 1979-88: %.1f%%   1989-97: %.1f%%   1998-2009: %.1f%%   2010-19: %.1f%%   2020-25: %.1f%%",
        p1*100, p2*100, p3*100, p4*100, p5*100),
sprintf("- Lowest single year of the full 47-year run: **%d (%.1f%%)**.", lowest_year, lowest_val*100),
sprintf("- 47-year mean (dashed line): %.1f%%.", overall_mean*100),
"- Unchanged since the backbench/frontbench role-tagging work (7 Sep) — this aggregate series",
"  was not touched by that split; these numbers were already current.",
"- For the construct-validity finding (does the trend survive within backbench/frontbench",
"  separately — yes, see Figure 3.3 and FIG33_FOOTNOTE_NOTES.md) and full sourcing history",
"  (Chamber-only vs Chamber+WH decision, ParlSpeech replacement, constituency-keyword cross-",
"  check), see FIG33_FOOTNOTE_NOTES.md — not repeated here."
)
writeLines(notes, file.path(PROJECT, "CH3_AGGREGATE_APPENDIX_NOTES.md"))
cat("notes  :", file.path(PROJECT, "CH3_AGGREGATE_APPENDIX_NOTES.md"), "\n")
cat(sprintf("periods: %.1f%% / %.1f%% / %.1f%% / %.1f%% / %.1f%%\n", p1*100, p2*100, p3*100, p4*100, p5*100))
